1218   *
  1219   * This is the set of XML parser options that can be passed down
  1220   * to the xmlReadDoc() and similar calls.
  1221   */
  1222  typedef enum {
  1223      XML_PARSE_RECOVER   = 1<<0, /* recover on errors */
  1224      XML_PARSE_NOENT     = 1<<1, /* substitute entities */
  1225      XML_PARSE_DTDLOAD   = 1<<2, /* load the external subset */
  1226      XML_PARSE_DTDATTR   = 1<<3, /* default DTD attributes */
  1227      XML_PARSE_DTDVALID  = 1<<4, /* validate with the DTD */
  1228      XML_PARSE_NOERROR   = 1<<5, /* suppress error reports */
  1229      XML_PARSE_NOWARNING = 1<<6, /* suppress warning reports */
  1230      XML_PARSE_PEDANTIC  = 1<<7, /* pedantic error reporting */
  1231      XML_PARSE_NOBLANKS  = 1<<8, /* remove blank nodes */
  1232      XML_PARSE_SAX1      = 1<<9, /* use the SAX1 interface internally */
  1233      XML_PARSE_XINCLUDE  = 1<<10,/* Implement XInclude substitution  */
  1234      XML_PARSE_NONET     = 1<<11,/* Forbid network access */
  1235      XML_PARSE_NODICT    = 1<<12,/* Do not reuse the context dictionary */
  1236      XML_PARSE_NSCLEAN   = 1<<13,/* remove redundant namespaces declarations */
  1237      XML_PARSE_NOCDATA   = 1<<14,/* merge CDATA as text nodes */
  1238      XML_PARSE_NOXINCNODE= 1<<15,/* do not generate XINCLUDE START/END nodes */
  1239      XML_PARSE_COMPACT   = 1<<16,/* compact small text nodes; no modification of
  1240                                     the tree allowed afterwards (will possibly
  1241                                     crash if you try to modify the tree) */
  1242      XML_PARSE_OLD10     = 1<<17,/* parse using XML-1.0 before update 5 */
  1243      XML_PARSE_NOBASEFIX = 1<<18,/* do not fixup XINCLUDE xml:base uris */
  1244      XML_PARSE_HUGE      = 1<<19,/* relax any hardcoded limit from the parser */
  1245      XML_PARSE_OLDSAX    = 1<<20,/* parse using SAX2 interface before 2.7.0 */
  1246      XML_PARSE_IGNORE_ENC= 1<<21,/* ignore internal document encoding hint */
  1247      XML_PARSE_BIG_LINES = 1<<22 /* Store big lines numbers in text PSVI field */
  1248  } xmlParserOption;
